window.RP_SESSION={"id":"S-21dd9e52b7a1","messages":[{"id":"RP-0178336","time":"2026-06-27T00:19:00+09:00","room":"RP","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"....심심하다.\"\n\n리키는 생각했다.\n요즘 할일이 너무 없다고.\n폐인처럼 지냈을때는 사실상 죽은 상태와 다름이 없었으니 제외하고,학파에 있었을 때보다 확연히 심심하다.\n물론 평화롭긴 하다만은.\n연구도,갈등도 없으니 잡일이라도 하고 싶건만...너무 미숙한터라 방해가 될까 걱정이다.\n\n\"잘까...\"","characters":["P-bb4b9d047737"]},{"id":"RP-0178337","time":"2026-06-27T00:25:00+09:00","room":"RP","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"라곤 했지만 아직 피곤하진 않다. 진짜 무료하고,또 무료할 뿐이니까.\n아직 들어온지 얼마 안된것도 있겠지만 아직 사람들과 말하는건 꽤나 어색하다.\n특히 살가운 사람.\n어떻게 그런지 모르겠다.\n난 죽어도 안될것 같은데.\n그런 생각을하며 1층으로 내려간다. 혹시 그나마 말 트인 사람들이 있을수도 있으니까.","characters":["P-bb4b9d047737"]},{"id":"RP-0178338","time":"2026-06-27T10:22:00+09:00","room":"RP","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-bb4b9d047737"]},{"id":"RP-0178339","time":"2026-06-27T10:22:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]}]};
